package com.kpriet.studentportal;
import javax.servlet.*;import javax.servlet.http.*;import java.io.*;import java.sql.*;import java.util.*;
public class StudentsServlet extends HttpServlet { protected void doGet(HttpServletRequest req,HttpServletResponse res)throws ServletException,IOException{if(req.getSession().getAttribute("loggedIn")==null){res.sendRedirect("login.jsp");return;} List<Map<String,Object>> list=new ArrayList<>(); try(Connection c=DB.get();PreparedStatement ps=c.prepareStatement("SELECT id,name,roll_number,email,course FROM students ORDER BY id")){ResultSet rs=ps.executeQuery();while(rs.next()){Map<String,Object> m=new HashMap<>();m.put("id",rs.getInt("id"));m.put("name",rs.getString("name"));m.put("roll",rs.getString("roll_number"));m.put("email",rs.getString("email"));m.put("course",rs.getString("course"));list.add(m);}}catch(SQLException e){throw new ServletException(e);}req.setAttribute("students",list);req.getRequestDispatcher("students.jsp").forward(req,res);} }
